// Parses the C2 stream: `event: text|completed|failed` frames separated by a blank line.
// Each frame is validated at run time; anything else is dropped (model and server output is untrusted).

export type StreamEvent =
  | { type: "text"; text: string }
  | { type: "completed" }
  | { type: "failed"; message: string };

export function parseFrame(frame: string): StreamEvent | null {
  let name = "";
  const data: string[] = [];
  for (const line of frame.split("\n")) {
    if (line.startsWith("event:")) name = line.slice(6).trim();
    else if (line.startsWith("data:")) data.push(line.slice(5).trim());
  }
  let body: unknown;
  try {
    body = JSON.parse(data.join("\n") || "{}");
  } catch {
    return null;
  }
  const record = typeof body === "object" && body !== null ? (body as Record<string, unknown>) : {};
  if (name === "text" && typeof record.text === "string") return { type: "text", text: record.text };
  if (name === "completed") return { type: "completed" };
  if (name === "failed") {
    return { type: "failed", message: typeof record.message === "string" ? record.message : "" };
  }
  return null;
}

export async function* readEvents(body: ReadableStream<Uint8Array>): AsyncGenerator<StreamEvent> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  try {
    for (;;) {
      const { done, value } = await reader.read();
      buffer += decoder.decode(value, { stream: !done }).replace(/\r\n/g, "\n");
      let end: number;
      while ((end = buffer.indexOf("\n\n")) !== -1) {
        const event = parseFrame(buffer.slice(0, end));
        buffer = buffer.slice(end + 2);
        if (event) yield event;
      }
      if (done) break;
    }
  } finally {
    reader.releaseLock();
  }
}
