// Message state for one assistant turn (C3): partial text is never shown as final.
import type { StreamEvent } from "./sse";

export type MessageStatus = "streaming" | "completed" | "failed";

export interface AssistantMessage {
  text: string;
  status: MessageStatus;
  error?: string;
}

export const FAILED_COPY = "The assistant could not finish this reply. Try asking again.";

export const startMessage = (): AssistantMessage => ({ text: "", status: "streaming" });

export function applyEvent(message: AssistantMessage, event: StreamEvent): AssistantMessage {
  if (message.status !== "streaming") return message; // terminal states are final
  if (event.type === "text") return { ...message, text: message.text + event.text };
  if (event.type === "completed") return { ...message, status: "completed" };
  // Server text is not shown raw: the design says errors are one plain sentence.
  return { ...message, status: "failed", error: FAILED_COPY };
}

// The stream ended, or the fetch threw, without a terminal event: that is a failure, never a completion.
export function endStream(message: AssistantMessage): AssistantMessage {
  return message.status === "streaming" ? { ...message, status: "failed", error: FAILED_COPY } : message;
}
