import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import { SafeText } from "../components/SafeText";
import { applyEvent, endStream, startMessage } from "./message";
import { readEvents } from "./sse";

function stream(chunks: string[]): ReadableStream<Uint8Array> {
  const enc = new TextEncoder();
  return new ReadableStream({
    start(c) {
      chunks.forEach((x) => c.enqueue(enc.encode(x)));
      c.close();
    },
  });
}
async function run(chunks: string[]) {
  let m = startMessage();
  const seen: string[] = [];
  for await (const e of readEvents(stream(chunks))) {
    m = applyEvent(m, e);
    seen.push(`${m.status}:${m.text}`);
  }
  return { m, seen };
}

describe("A1 streaming then completed", () => {
  it("shows text as it arrives and completes only after `completed`", async () => {
    const { m, seen } = await run([
      'event: text\ndata: {"text":"HR-04 "}\n\nevent: te', // frame split across chunks
      'xt\ndata: {"text":"§2.3"}\n\n',
      "event: completed\ndata: {}\n\n",
    ]);
    expect(seen).toEqual(["streaming:HR-04 ", "streaming:HR-04 §2.3", "completed:HR-04 §2.3"]);
    expect(m.status).toBe("completed");
  });
  it("a stream that just ends is failed, not completed", async () => {
    const { m } = await run(['event: text\ndata: {"text":"part"}\n\n']);
    expect(endStream(m).status).toBe("failed");
  });
});

describe("A2 failed keeps its text", () => {
  it("keeps partial text and marks failed, without the server's raw message", async () => {
    const { m } = await run([
      'event: text\ndata: {"text":"partial"}\n\n',
      'event: failed\ndata: {"message":"boom: stack trace"}\n\n',
    ]);
    expect(m).toMatchObject({ status: "failed", text: "partial" });
    expect(m.error).not.toContain("boom");
  });
});

describe("A3 hostile model output is inert", () => {
  const hostile =
    'Hi <img src=x onerror=alert(1)> [click](javascript:alert(1)) ![t](https://evil.example/p.png) [ok](https://example.com/a)';
  const html = renderToStaticMarkup(createElement(SafeText, { source: hostile }));
  it("renders no img, no javascript: link and no live onerror", () => {
    expect(html).not.toContain("<img");
    expect(html).not.toMatch(/href="javascript/i);
    expect(html).not.toMatch(/<[^>]*onerror/i); // appears only as escaped text
    expect(html).toContain("&lt;img src=x onerror=alert(1)&gt;");
  });
  it("still renders a safe https link", () => {
    expect(html).toContain('href="https://example.com/a"');
  });
});
